#!/usr/bin/env python3
import argparse
import os
import shutil
import sqlite3
import sys
from datetime import datetime
from pathlib import Path


APP_NAME = "todo"
DB_PATH = Path(os.environ.get("TODO_DB", Path.home() / ".todo.sqlite3"))


class TodoError(Exception):
    pass


def now():
    return datetime.now().replace(microsecond=0).isoformat(sep=" ")


def connect(db_path=DB_PATH):
    try:
        conn = sqlite3.connect(db_path)
        conn.row_factory = sqlite3.Row
        return conn
    except sqlite3.Error as exc:
        raise TodoError(f"Could not open database: {exc}") from exc


def init_db(conn):
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS tasks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                completed INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                completed_at TEXT
            )
            """
        )
        conn.commit()
    except sqlite3.Error as exc:
        raise TodoError(f"Could not initialize database: {exc}") from exc


def add_task(conn, title):
    title = " ".join(title).strip() if isinstance(title, list) else title.strip()
    if not title:
        raise TodoError("Task title cannot be empty.")

    timestamp = now()
    try:
        cur = conn.execute(
            """
            INSERT INTO tasks (title, completed, created_at, updated_at, completed_at)
            VALUES (?, 0, ?, ?, NULL)
            """,
            (title, timestamp, timestamp),
        )
        conn.commit()
        task = get_task(conn, cur.lastrowid)
        print_task_detail(task, prefix="Added")
    except sqlite3.Error as exc:
        raise TodoError(f"Could not add task: {exc}") from exc


def get_task(conn, task_id):
    try:
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
    except sqlite3.Error as exc:
        raise TodoError(f"Could not retrieve task: {exc}") from exc

    if row is None:
        raise TodoError(f"No task found with id {task_id}.")
    return row


def list_tasks(conn, status):
    query = "SELECT * FROM tasks"
    params = []

    if status == "pending":
        query += " WHERE completed = 0"
    elif status == "completed":
        query += " WHERE completed = 1"

    query += " ORDER BY completed ASC, id ASC"

    try:
        rows = conn.execute(query, params).fetchall()
    except sqlite3.Error as exc:
        raise TodoError(f"Could not list tasks: {exc}") from exc

    print_task_table(rows)


def complete_task(conn, task_id):
    task = get_task(conn, task_id)

    if task["completed"]:
        print_task_detail(task, prefix="Already completed")
        return

    timestamp = now()
    try:
        conn.execute(
            """
            UPDATE tasks
            SET completed = 1, updated_at = ?, completed_at = ?
            WHERE id = ?
            """,
            (timestamp, timestamp, task_id),
        )
        conn.commit()
        task = get_task(conn, task_id)
        print_task_detail(task, prefix="Completed")
    except sqlite3.Error as exc:
        raise TodoError(f"Could not complete task: {exc}") from exc


def delete_task(conn, task_id):
    task = get_task(conn, task_id)

    try:
        conn.execute("DELETE FROM tasks WHERE id = ?", (task_id,))
        conn.commit()
        print_task_detail(task, prefix="Deleted")
    except sqlite3.Error as exc:
        raise TodoError(f"Could not delete task: {exc}") from exc


def truncate(text, width):
    text = "" if text is None else str(text)
    if width <= 0:
        return ""
    if len(text) <= width:
        return text
    if width == 1:
        return "…"
    return text[: width - 1] + "…"


def print_task_detail(task, prefix="Task"):
    status = "✓ completed" if task["completed"] else "• pending"
    print(f"{prefix}: #{task['id']} [{status}] {task['title']}")
    print(f"Created:   {task['created_at']}")
    print(f"Updated:   {task['updated_at']}")
    if task["completed_at"]:
        print(f"Completed: {task['completed_at']}")


def print_task_table(rows):
    if not rows:
        print("No tasks found.")
        return

    terminal_width = shutil.get_terminal_size((100, 20)).columns

    headers = ["ID", "Status", "Task", "Created", "Updated", "Completed"]
    fixed_widths = {
        "ID": max(2, min(6, max(len(str(row["id"])) for row in rows))),
        "Status": 9,
        "Created": 19,
        "Updated": 19,
        "Completed": 19,
    }

    separators = 3 * (len(headers) - 1)
    fixed_total = sum(fixed_widths.values()) + separators
    task_width = max(12, terminal_width - fixed_total)
    task_width = min(task_width, 60)

    widths = {
        "ID": fixed_widths["ID"],
        "Status": fixed_widths["Status"],
        "Task": task_width,
        "Created": fixed_widths["Created"],
        "Updated": fixed_widths["Updated"],
        "Completed": fixed_widths["Completed"],
    }

    def line(char="-"):
        return char * (
            sum(widths[h] for h in headers) + separators
        )

    def row(values):
        return " | ".join(
            truncate(values[h], widths[h]).ljust(widths[h]) for h in headers
        )

    print(row({h: h for h in headers}))
    print(line())

    for task in rows:
        values = {
            "ID": str(task["id"]),
            "Status": "done" if task["completed"] else "pending",
            "Task": task["title"],
            "Created": task["created_at"],
            "Updated": task["updated_at"],
            "Completed": task["completed_at"] or "",
        }
        print(row(values))


def positive_int(value):
    try:
        number = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError("must be an integer")
    if number <= 0:
        raise argparse.ArgumentTypeError("must be a positive integer")
    return number


def build_parser():
    parser = argparse.ArgumentParser(
        prog=APP_NAME,
        description="A small SQLite-backed command-line todo app.",
    )
    parser.add_argument(
        "--db",
        default=str(DB_PATH),
        help=f"SQLite database path. Defaults to {DB_PATH}",
    )

    subparsers = parser.add_subparsers(dest="command", required=True)

    add_parser = subparsers.add_parser("add", help="Add a new task.")
    add_parser.add_argument("title", nargs="+", help="Task title.")

    list_parser = subparsers.add_parser("list", help="List tasks.")
    list_group = list_parser.add_mutually_exclusive_group()
    list_group.add_argument(
        "--all",
        action="store_const",
        const="all",
        dest="status",
        help="Show all tasks.",
    )
    list_group.add_argument(
        "--pending",
        action="store_const",
        const="pending",
        dest="status",
        help="Show pending tasks.",
    )
    list_group.add_argument(
        "--completed",
        action="store_const",
        const="completed",
        dest="status",
        help="Show completed tasks.",
    )
    list_parser.set_defaults(status="all")

    complete_parser = subparsers.add_parser("complete", help="Mark a task as completed.")
    complete_parser.add_argument("id", type=positive_int, help="Task id.")

    delete_parser = subparsers.add_parser("delete", help="Delete a task.")
    delete_parser.add_argument("id", type=positive_int, help="Task id.")

    return parser


def run(args):
    db_path = Path(args.db).expanduser()

    try:
        db_path.parent.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise TodoError(f"Could not create database directory: {exc}") from exc

    with connect(db_path) as conn:
        init_db(conn)

        if args.command == "add":
            add_task(conn, args.title)
        elif args.command == "list":
            list_tasks(conn, args.status)
        elif args.command == "complete":
            complete_task(conn, args.id)
        elif args.command == "delete":
            delete_task(conn, args.id)
        else:
            raise TodoError(f"Unknown command: {args.command}")


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)

    try:
        run(args)
        return 0
    except TodoError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nError: interrupted", file=sys.stderr)
        return 130


if __name__ == "__main__":
    sys.exit(main())

