class ListNode<K, V> {
  key: K | null;
  value: V | null;
  prev: ListNode<K, V> | null = null;
  next: ListNode<K, V> | null = null;

  constructor(key: K | null = null, value: V | null = null) {
    this.key = key;
    this.value = value;
  }
}

export class LRUCache<K, V> {
  private readonly capacity: number;
  private readonly map = new Map<K, ListNode<K, V>>();
  private readonly head = new ListNode<K, V>();
  private readonly tail = new ListNode<K, V>();

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("Capacity must be a positive integer");
    }

    this.capacity = capacity;
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key: K): V | -1 {
    const node = this.map.get(key);

    if (!node) {
      return -1;
    }

    this.moveToFront(node);
    return node.value as V;
  }

  put(key: K, value: V): void {
    const existingNode = this.map.get(key);

    if (existingNode) {
      existingNode.value = value;
      this.moveToFront(existingNode);
      return;
    }

    if (this.map.size === this.capacity) {
      const leastRecentlyUsed = this.tail.prev;

      if (leastRecentlyUsed && leastRecentlyUsed !== this.head) {
        this.removeNode(leastRecentlyUsed);
        this.map.delete(leastRecentlyUsed.key as K);
      }
    }

    const newNode = new ListNode(key, value);
    this.map.set(key, newNode);
    this.addToFront(newNode);
  }

  private moveToFront(node: ListNode<K, V>): void {
    this.removeNode(node);
    this.addToFront(node);
  }

  private addToFront(node: ListNode<K, V>): void {
    node.prev = this.head;
    node.next = this.head.next;

    if (this.head.next) {
      this.head.next.prev = node;
    }

    this.head.next = node;
  }

  private removeNode(node: ListNode<K, V>): void {
    if (node.prev) {
      node.prev.next = node.next;
    }

    if (node.next) {
      node.next.prev = node.prev;
    }

    node.prev = null;
    node.next = null;
  }
}

const basicCache = new LRUCache<number, number>(2);
basicCache.put(1, 10);
basicCache.put(2, 20);
console.assert(basicCache.get(1) === 10, "basic get/put: expected key 1 to return 10");
console.assert(basicCache.get(2) === 20, "basic get/put: expected key 2 to return 20");
console.assert(basicCache.get(3) === -1, "basic get/put: expected missing key to return -1");

const evictionCache = new LRUCache<number, number>(2);
evictionCache.put(1, 10);
evictionCache.put(2, 20);
evictionCache.put(3, 30);
console.assert(evictionCache.get(1) === -1, "capacity eviction: expected key 1 to be evicted");
console.assert(evictionCache.get(2) === 20, "capacity eviction: expected key 2 to remain");
console.assert(evictionCache.get(3) === 30, "capacity eviction: expected key 3 to remain");

const accessOrderCache = new LRUCache<number, number>(2);
accessOrderCache.put(1, 10);
accessOrderCache.put(2, 20);
console.assert(accessOrderCache.get(1) === 10, "access-order update: expected key 1 to return 10");
accessOrderCache.put(3, 30);
console.assert(accessOrderCache.get(2) === -1, "access-order update: expected key 2 to be evicted");
console.assert(accessOrderCache.get(1) === 10, "access-order update: expected key 1 to remain");
console.assert(accessOrderCache.get(3) === 30, "access-order update: expected key 3 to remain");

const overwriteCache = new LRUCache<number, number>(2);
overwriteCache.put(1, 10);
overwriteCache.put(2, 20);
overwriteCache.put(1, 100);
console.assert(overwriteCache.get(1) === 100, "overwrite existing key: expected key 1 to return updated value");
overwriteCache.put(3, 30);
console.assert(overwriteCache.get(2) === -1, "overwrite existing key: expected key 2 to be evicted");
console.assert(overwriteCache.get(1) === 100, "overwrite existing key: expected key 1 to remain");
console.assert(overwriteCache.get(3) === 30, "overwrite existing key: expected key 3 to remain");

