Minimal fix: make the auth middleware read the same header that `/login` sends: `x-auth-token`.

### Changed `middleware/auth.js`

```javascript
// Authentication middleware
function authMiddleware(req, res, next) {
  const token = req.headers['x-auth-token'];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = Buffer.from(token, 'base64').toString('utf8');
    const [userId, timestamp] = decoded.split(':');

    if (!userId || !timestamp) {
      return res.status(401).json({ error: 'Invalid token format' });
    }

    // Token expires after 1 hour
    if (Date.now() - parseInt(timestamp) > 3600000) {
      return res.status(401).json({ error: 'Token expired' });
    }

    req.userId = parseInt(userId);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

module.exports = authMiddleware;
```

### What changed

Only this line changed:

```javascript
const token = req.headers.authorization;
```

to:

```javascript
const token = req.headers['x-auth-token'];
```

### Why

The login route sends the token using this response header:

```javascript
res.set('x-auth-token', token);
```

So protected requests should provide the token back using the same header:

```http
x-auth-token: <token>
```

The middleware was checking `authorization`, so it never found the token and returned `401 No token provided`. This makes both sides use `x-auth-token` consistently.

